import string

def gen(rng):
    alpha = string.ascii_letters + string.digits
    def rs(n, pool=alpha):
        return ''.join(rng.choice(pool) for _ in range(n))
    tests = ['a\nb', 'Hello\nWorld', '12\n34', 'x\nabcxyz', '0\n0', 'Z\n9', 'abc\nabc', '007\n7', 'A1b2\nC3d4']
    for _ in range(12):
        tests.append(rs(rng.randint(1, 30)) + '\n' + rs(rng.randint(1, 30)))
    for _ in range(4):
        tests.append(rs(rng.randint(1, 5), 'ab') + '\n' + rs(rng.randint(1, 5), '01'))
    tests.append(rs(100000) + '\n' + rs(100000))
    tests.append('a' * 100000 + '\n' + 'b' * 100000)
    tests.append('Q' + '\n' + rs(100000))
    return tests

